export type WorkersMultipartScript = {
  /**
   * An array of modules (often JavaScript files) comprising a Worker script. At least one module must be present and referenced in the metadata as `main_module` or `body_part` by filename.<br/>Possible Content-Type(s) are: `application/javascript+module`, `text/javascript+module`, `application/javascript`, `text/javascript`, `text/x-python`, `text/x-python-requirement`, `application/wasm`, `text/plain`, `application/octet-stream`, `application/source-map`.
   */
  files?: Array<Blob | File>;
  /**
   * JSON-encoded metadata about the uploaded parts and Worker configuration.
   */
  metadata: {
    assets?: WorkersAssets2;
    bindings?: WorkersBindings;
    /**
     * Name of the uploaded file that contains the script (e.g. the file adding a listener to the `fetch` event). Indicates a `service worker syntax` Worker.
     */
    body_part?: string;
    cache_options?: WorkersCacheOptions;
    compatibility_date?: WorkersCompatibilityDate;
    compatibility_flags?: WorkersCompatibilityFlags;
    /**
     * Summary of the declarative exports reconciliation that ran
     * on this upload. Populated only when the uploaded metadata
     * included an `exports` block. Durable Object entries drive
     * reconciliation; `type: worker` entries do not contribute to
     * this summary.
     *
     */
    exports_reconciliation?: WorkersExportsReconciliationResult;
    /**
     * Retain assets which exist for a previously uploaded Worker version; used in lieu of providing a completion token. An explicit `assets` upload takes precedence over `keep_assets`.
     */
    keep_assets?: boolean;
    /**
     * List of binding types to keep from previous_upload.
     */
    keep_bindings?: Array<string>;
    limits?: WorkersLimits;
    logpush?: WorkersLogpush;
    /**
     * Name of the uploaded file that contains the main module (e.g. the file exporting a `fetch` handler). Indicates a `module syntax` Worker.
     */
    main_module?: string;
    observability?: WorkersObservability2;
    /**
     * The list of npm packages that were installed and used when this Worker
     * version was built.
     *
     */
    package_dependencies?: Array<{
      /**
       * The exact version that was resolved and installed by the package manager.
       */
      installedVersion: string;
      /**
       * The npm package name.
       */
      name: string;
      /**
       * The version constraint as written in package.json.
       */
      packageJsonVersion: string;
    }>;
    placement?: WorkersPlacementInfo;
    /**
     * List of strings to use as tags for this Worker.
     */
    tags?: Array<string>;
    tail_consumers?: WorkersTailConsumers;
    usage_model?: WorkersUsageModel;
  };
};

/**
 * Configuration for assets within a Worker.
 */
export type WorkersAssets2 = {
  /**
   * Configuration for assets within a Worker.
   */
  config?: {
    /**
     * The contents of a _headers file (used to attach custom headers on asset responses).
     */
    _headers?: string;
    /**
     * The contents of a _redirects file (used to apply redirects or proxy paths ahead of asset serving).
     */
    _redirects?: string;
    /**
     * The public URL path prefix under which assets are served. A null request value resets it to `/`; responses represent the root as `/`. All versions in a gradual deployment must use the same canonical value. To change it, first deploy the version containing the change at 100%.
     */
    base_path?: string | null;
    /**
     * Determines the redirects and rewrites of requests for HTML content.
     */
    html_handling?: "auto-trailing-slash" | "force-trailing-slash" | "drop-trailing-slash" | "none";
    /**
     * Determines the response when a request does not match a static asset, and there is no Worker script.
     */
    not_found_handling?: "none" | "404-page" | "single-page-application";
    run_worker_first?: Array<string> | boolean;
    /**
     * When true and the incoming request matches an asset, that will be served instead of invoking the Worker script. When false, requests will always invoke the Worker script.
     *
     * @deprecated
     */
    serve_directly?: boolean;
  };
  /**
   * Token provided upon successful upload of all files from a registered manifest.
   */
  jwt?: string;
};

