/**
 * The v4 error envelope returned with HTTP 400 when one or more
 * declared `exports` entries fail reconciliation (error code
 * 100402). The top-level error `message` aggregates the per-class
 * failures as human-readable prose; the structured per-class payload
 * is carried in `errors[].meta.details`, sorted by class name.
 *
 */
export type WorkersExportsReconciliationErrorResponse = {
  errors: Array<{
    code: 100402;
    /**
     * Aggregate, multi-line, human-readable summary of every
     * per-class reconciliation failure.
     *
     */
    message: string;
    meta: {
      /**
       * Structured per-class reconciliation failures, sorted
       * by class name.
       *
       */
      details: Array<WorkersExportsReconciliationError>;
    };
  }>;
  messages: WorkersMessages;
  result: null;
  success: false;
};

/**
 * A single blocking reconciliation error. Returned in the v4 error
 * envelope under `meta.details` on the exports reconciliation
 * failure error (code 100402). All per-class failures are reported
 * together, sorted by class name.
 *
 */
export type WorkersExportsReconciliationError = {
  /**
   * The class name the error is about.
   */
  class: string;
  /**
   * Human-readable explanation.
   */
  message: string;
  /**
   * The provisioned namespace the error relates to, when applicable.
   */
  namespace_id?: string;
  /**
   * Other Workers in the account whose bindings block the
   * operation (e.g. a `deleted` tombstone blocked by external
   * bindings).
   *
   */
  referencing_scripts?: Array<string>;
  scenario: WorkersExportsReconciliationScenario;
  /**
   * An actionable hint for resolving the error, when available.
   */
  suggestion?: string;
};

