/**
 * Summary of what the declarative exports reconciliation did on this
 * upload. Present only on uploads that included an `exports` block.
 * Reconciliation acts on Durable Object entries; `type: worker`
 * entries in the same map do not participate. Every array is always
 * present (possibly empty) so clients can iterate unconditionally.
 * Clients should surface `warnings` prominently, render `info` at
 * lower visibility, and use `removable_entries` as the "safe to
 * delete from your config" hint.
 *
 */
export type WorkersExportsReconciliationResultWritable = {
  /**
   * Class names for which a new namespace was provisioned.
   */
  created: Array<string>;
  /**
   * Class names whose namespace was deleted by a `deleted` tombstone.
   */
  deleted: Array<string>;
  /**
   * Non-blocking info entries (stale tombstones, tombstone applied
   * with class still in code). See `exports_reconciliation_info`.
   *
   */
  info: Array<WorkersExportsReconciliationInfo>;
  /**
   * Source class names whose tombstone entry is now stale and safe
   * to delete from `exports` (no remaining referencing scripts).
   *
   */
  removable_entries: Array<string>;
  /**
   * Applied `renamed` tombstones.
   */
  renamed: Array<WorkersExportsReconciliationRename>;
  /**
   * Phase-1 transfer hints recorded on the target side.
   */
  transfer_pending: Array<WorkersExportsReconciliationTransferPending>;
  /**
   * Committed `transferred` tombstones (phase-2).
   */
  transferred: Array<WorkersExportsReconciliationTransfer>;
  /**
   * Class names whose provisioned namespace was mutated in place.
   */
  updated: Array<string>;
  /**
   * Non-blocking warnings. See `exports_reconciliation_warning`.
   */
  warnings: Array<WorkersExportsReconciliationWarning>;
};

